const skor = parseInt($json.skor_urgensi_hukum) || 0;
const u    = ($json.urgensi_sinyal || '').trim();
const lang = ($json.bahasa_output  || 'en').toLowerCase();

// ── Label urgensi per bahasa ─────────────────────────────────────────────────
const LABEL_TINGGI  = { id: 'Tinggi',    en: 'High',   nl: 'Hoog'      };
const LABEL_SEDANG  = { id: 'Sedang',    en: 'Medium', nl: 'Gemiddeld' };
const LABEL_RENDAH  = { id: 'Rendah',    en: 'Low',    nl: 'Laag'      };

const isTinggi = skor >= 90
  || u === LABEL_TINGGI.id
  || u === LABEL_TINGGI.en
  || u === LABEL_TINGGI.nl;

const isSedang = !isTinggi && (
     skor >= 70
  || skor >= 50
  || u === LABEL_SEDANG.id
  || u === LABEL_SEDANG.en
  || u === LABEL_SEDANG.nl
);

// ── Routing ──────────────────────────────────────────────────────────────────
let route, channel, sla_jam;

if (skor >= 90 || isTinggi) {
  route   = 'kritis_voice_call';   // akut → telepon langsung
  channel = 'voice_call';
  sla_jam = 24;
} else if (skor >= 70 || isSedang) {
  route   = 'tinggi_whatsapp';     // Meldcode terpicu → WhatsApp
  channel = 'whatsapp';
  sla_jam = 48;
} else if (skor >= 50) {
  route   = 'sedang_whatsapp';     // risiko sedang → WhatsApp
  channel = 'whatsapp';
  sla_jam = 168;                   // 1 minggu
} else {
  route   = 'rendah_dossier';      // informatif → catat saja
  channel = 'dossier';
  sla_jam = null;
}

// ── Deadline eskalasi (ISO string, null jika tidak berlaku) ──────────────────
const waktu_eskalasi = sla_jam !== null
  ? new Date(Date.now() + sla_jam * 3600 * 1000).toISOString()
  : '';

return [{
  json: {
    ...$json,
    skor_urgensi_hukum : skor,
    _route             : route,
    _channel           : channel,
    _sla_jam           : sla_jam,
    waktu_eskalasi     : waktu_eskalasi || $json.waktu_eskalasi || ''
  }
}];

const d = items[0].json;
const sinyals = d.sinyal || [];

// ── Ambil metadata: prioritas metadata_kasus dari AI, lalu fallback ke node input ──
let meta = {};

// Layer 1: metadata_kasus yang sudah di-parse AI (dari prompt baru)
if (typeof d.metadata_kasus === 'object' && d.metadata_kasus !== null) {
  meta = { ...d.metadata_kasus };
}

// Layer 2: fallback ke node input manual / WhatsApp (isi field yang masih kosong)
let metaNode = {};
try { metaNode = $('Fungsi: Validasi Input Manual').first().json; } catch(e) {}
try { if (!metaNode.nama_pelapor) metaNode = $('Fungsi: Validasi Input WhatsApp').first().json; } catch(e) {}

// Merge: metadata_kasus dari AI diutamakan, node input sebagai fallback
const nama_pengirim    = meta.nama_pengirim     || metaNode.nama_pelapor   || 'Anonim';
const nomor_pengirim   = meta.nomor_pengirim    || metaNode.wa_chat_id     || '';
const nama_program     = meta.program           || metaNode.nama_program   || '';
const nama_lokasi      = meta.lokasi            || metaNode.nama_lokasi    || '';
const level_laporan    = meta.level_laporan     || metaNode.level_laporan  || '';
const urgensi_awal     = meta.urgensi_awal      || metaNode.urgensi_laporan|| '';
const timestamp_ai     = meta.timestamp_laporan || '';
const jenis_sumber     = metaNode.jenis_sumber  || (nomor_pengirim ? 'whatsapp' : 'input-manual');
const wa_chat_id       = metaNode.wa_chat_id    || nomor_pengirim || '';

// ── Generate ticket ID ───────────────────────────────────────────────────────
const td = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const tr = Math.floor(Math.random() * 9000 + 1000);

// ── Hitung skor urgensi tertinggi dari semua sinyal ──────────────────────────
const maxSkor = sinyals.length > 0
  ? Math.max(...sinyals.map(s => typeof s.skor_urgensi_hukum === 'number' ? s.skor_urgensi_hukum : 0))
  : 0;

// Tentukan status eskalasi otomatis berdasarkan skor tertinggi
const status_eskalasi = maxSkor >= 90 ? 'KRITIS'
  : maxSkor >= 70 ? 'Tinggi'
  : maxSkor >= 50 ? 'Sedang'
  : 'Normal';

// ── Base ticket fields ───────────────────────────────────────────────────────
const base = {
  ticket_id               : 'OZJ-' + td + '-' + tr,
  bahasa_output           : d.bahasa_output       || 'en',
  ringkasan_sinyal        : d.ringkasan            || '',
  risiko_teridentifikasi  : Array.isArray(d.risiko)      ? d.risiko.join('; ')      : '',
  rekomendasi_ai          : Array.isArray(d.rekomendasi) ? d.rekomendasi.join('; ') : '',
  // Identitas pelapor
  nama_pengirim           : nama_pengirim,
  nomor_pengirim          : nomor_pengirim,
  nama_program            : nama_program,
  nama_lokasi             : nama_lokasi,
  level_laporan           : level_laporan,
  urgensi_awal            : urgensi_awal,
  timestamp_laporan_ai    : timestamp_ai,
  jenis_sumber            : jenis_sumber,
  wa_chat_id              : wa_chat_id,
  // Ticket status
  waktu_catat             : new Date().toISOString(),
  status_ticket           : 'Open',
  status_eskalasi         : status_eskalasi,
  skor_urgensi_tertinggi  : maxSkor,
  waktu_eskalasi          : '',
  rekomendasi_keputusan   : ''
};

// ── Helper: flatten rekomendasi_respons jadi field datar ────────────────────
function flattenRR(rr) {
  const safe = (typeof rr === 'object' && rr !== null) ? rr : {};
  return {
    rr_tenggat_waktu        : safe.tenggat_waktu        || '',
    rr_tindakan_utama       : safe.tindakan_utama       || '',
    rr_pihak_yang_dihubungi : safe.pihak_yang_dihubungi || '',
    rr_langkah_dokumentasi  : safe.langkah_dokumentasi  || ''
  };
}

// ── Fallback jika tidak ada sinyal ──────────────────────────────────────────
if (sinyals.length === 0) {
  return [{
    json: {
      ...base,
      judul_sinyal       : 'Tidak ada sinyal terdeteksi',
      deskripsi_sinyal   : '',
      level_sinyal       : '',
      urgensi_sinyal     : '',
      kategori_sinyal    : '',
      skor_urgensi_hukum : 0,
      dasar_hukum        : '',
      sinyal_index       : 0,
      sinyal_total       : 0,
      ...flattenRR({})
    }
  }];
}

// ── Map setiap sinyal jadi satu ticket row ───────────────────────────────────
return sinyals.map((s, i) => ({
  json: {
    ...base,
    ticket_id          : base.ticket_id + (i > 0 ? '-' + (i + 1) : ''),
    sinyal_index       : i + 1,
    sinyal_total       : sinyals.length,
    judul_sinyal       : s.judul              || `Sinyal ${i + 1}`,
    deskripsi_sinyal   : s.deskripsi          || '',
    level_sinyal       : s.level              || '',
    urgensi_sinyal     : s.urgensi            || '',
    kategori_sinyal    : s.kategori           || '',
    skor_urgensi_hukum : typeof s.skor_urgensi_hukum === 'number' ? s.skor_urgensi_hukum : 0,
    dasar_hukum        : s.dasar_hukum        || '',
    ...flattenRR(s.rekomendasi_respons)
  }
}));

// Parsing output Gemini — mendukung berbagai format response
let raw = '';
if (typeof $json.text === 'string' && $json.text.length > 0) {
  raw = $json.text;
} else if ($json.candidates && Array.isArray($json.candidates)) {
  raw = ($json.candidates[0]?.content?.parts || []).map(p => p.text || '').join('');
} else if ($json.content?.parts) {
  raw = $json.content.parts.map(p => p.text || '').join('');
} else if (Array.isArray($json.content) && $json.content[0]?.text) {
  raw = $json.content.map(c => c.text || '').join('');
} else if ($json.choices && Array.isArray($json.choices)) {
  raw = $json.choices[0]?.message?.content || '';
} else if (typeof $json.output === 'string') {
  raw = $json.output;
} else if (typeof $json.response === 'string') {
  raw = $json.response;
}

// Bersihkan markdown/backtick dari output AI
const cleaned = raw
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .replace(/^\s*`+|`+\s*$/g, '')
  .trim();

let result;
try {
  const jsonStart = cleaned.indexOf('{');
  const jsonEnd   = cleaned.lastIndexOf('}');
  if (jsonStart === -1 || jsonEnd <= jsonStart) throw new Error('Tidak ada JSON valid ditemukan');
  result = JSON.parse(cleaned.substring(jsonStart, jsonEnd + 1));
  if (typeof result !== 'object' || result === null || Array.isArray(result)) throw new Error('Result bukan object');

  // Validasi bahasa
  const VALID_LANG = ['id', 'en', 'nl'];
  result.bahasa_output = VALID_LANG.includes(result.bahasa_output) ? result.bahasa_output : 'en';

  // Normalisasi metadata_kasus
  const mk = (typeof result.metadata_kasus === 'object' && result.metadata_kasus !== null) ? result.metadata_kasus : {};
  result.metadata_kasus = {
    nama_pengirim    : mk.nama_pengirim     || '',
    nomor_pengirim   : mk.nomor_pengirim    || '',
    timestamp_laporan: mk.timestamp_laporan || '',
    program          : mk.program           || '',
    lokasi           : mk.lokasi            || '',
    level_laporan    : mk.level_laporan     || '',
    urgensi_awal     : mk.urgensi_awal      || ''
  };

  // Normalisasi duplikasi — PENTING untuk IF node berikutnya
  const dup = (typeof result.duplikasi === 'object' && result.duplikasi !== null) ? result.duplikasi : {};
  result.duplikasi = {
    status     : dup.status === true || dup.status === 'true',
    ref_ticket : typeof dup.ref_ticket === 'string' ? dup.ref_ticket : '',
    catatan    : typeof dup.catatan   === 'string' ? dup.catatan   : ''
  };

  result.ringkasan   = typeof result.ringkasan === 'string' ? result.ringkasan : '';
  result.risiko      = Array.isArray(result.risiko)      ? result.risiko      : [];
  result.rekomendasi = Array.isArray(result.rekomendasi) ? result.rekomendasi : [];

  // Normalisasi sinyal
  result.sinyal = Array.isArray(result.sinyal) ? result.sinyal.map((s, idx) => {
    if (typeof s !== 'object' || s === null) return null;
    const rr   = (typeof s.rekomendasi_respons === 'object' && s.rekomendasi_respons !== null) ? s.rekomendasi_respons : {};
    const skor = typeof s.skor_urgensi_hukum === 'number' ? Math.min(100, Math.max(0, s.skor_urgensi_hukum)) : 0;
    return {
      judul              : s.judul    || ('Sinyal ' + (idx + 1)),
      deskripsi          : s.deskripsi || '',
      level              : s.level    || '',
      urgensi            : s.urgensi  || '',
      kategori           : s.kategori || '',
      skor_urgensi_hukum : skor,
      dasar_hukum        : s.dasar_hukum || '',
      rekomendasi_respons: {
        tenggat_waktu       : rr.tenggat_waktu        || '',
        tindakan_utama      : rr.tindakan_utama        || '',
        pihak_yang_dihubungi: rr.pihak_yang_dihubungi || '',
        langkah_dokumentasi : rr.langkah_dokumentasi  || ''
      }
    };
  }).filter(Boolean) : [];

} catch(e) {
  result = {
    bahasa_output : 'en',
    metadata_kasus: { nama_pengirim: '', nomor_pengirim: '', timestamp_laporan: '', program: '', lokasi: '', level_laporan: '', urgensi_awal: '' },
    duplikasi     : { status: false, ref_ticket: '', catatan: '' },
    ringkasan     : 'Parse gagal: ' + e.message,
    sinyal        : [], risiko: [], rekomendasi: [],
    _parse_error  : e.message,
    _raw_snippet  : raw.substring(0, 500)
  };
}

return [{ json: result }];

const now     = new Date();
const todayStr = now.toISOString().slice(0, 10); // "2026-03-10"

// ── Helper: normalize tanggal ke YYYY-MM-DD ──────────────────────────────────
function toDateStr(str) {
  if (!str) return '';
  return String(str).trim().replace(' ', 'T').slice(0, 10);
}

// ── Helper: normalize level sinyal ke Mikro/Meso/Makro ──────────────────────
function normalizeLevel(v) {
  const map = {
    'mikro'  : 'Mikro', 'micro'  : 'Mikro',
    'meso'   : 'Meso',  'medium' : 'Meso',
    'makro'  : 'Makro', 'macro'  : 'Makro'
  };
  return map[(v || '').toLowerCase()] || v || '—';
}

// ── Helper: normalize urgensi ke Rendah/Sedang/Tinggi ───────────────────────
function normalizeUrgensi(v) {
  const map = {
    'rendah'    : 'Rendah', 'low'  : 'Rendah', 'laag'      : 'Rendah',
    'sedang'    : 'Sedang', 'medium': 'Sedang', 'gemiddeld' : 'Sedang',
    'tinggi'    : 'Tinggi', 'high' : 'Tinggi', 'hoog'      : 'Tinggi'
  };
  return map[(v || '').toLowerCase()] || v || '—';
}

// ── Filter: hanya tiket hari ini yang valid (punya ticket_id & status_ticket) ─
const today = items.filter(i => {
  const d = i.json;
  if (!d.ticket_id || !d.status_ticket) return false;          // skip row tidak lengkap
  if (d.judul_sinyal === 'Tidak ada sinyal') return false;      // skip parse gagal
  return toDateStr(d.waktu_catat) === todayStr;
});

// ── Hitung statistik ─────────────────────────────────────────────────────────
let mikro = 0, meso = 0, makro = 0;
let rendah = 0, sedang = 0, tinggi = 0;
let eskalasi = 0, open = 0;

today.forEach(i => {
  const d       = i.json;
  const level   = normalizeLevel(d.level_sinyal);
  const urgensi = normalizeUrgensi(d.urgensi_sinyal);

  if (level   === 'Mikro')  mikro++;
  if (level   === 'Meso')   meso++;
  if (level   === 'Makro')  makro++;
  if (urgensi === 'Rendah') rendah++;
  if (urgensi === 'Sedang') sedang++;
  if (urgensi === 'Tinggi') tinggi++;

  if (d.status_ticket   === 'Open')      open++;
  if (d.status_eskalasi === 'Escalated'
   || d.status_eskalasi === 'Tinggi'
   || d.status_eskalasi === 'KRITIS')    eskalasi++;
});

// ── Buat teks konteks untuk AI summary ──────────────────────────────────────
const teks_konteks = today
  .filter(i => i.json.judul_sinyal)
  .map(i => {
    const d       = i.json;
    const level   = normalizeLevel(d.level_sinyal);
    const urgensi = normalizeUrgensi(d.urgensi_sinyal);
    const skor    = d.skor_urgensi_hukum || 0;
    const hukum   = d.dasar_hukum ? ` | ${d.dasar_hukum}` : '';
    return `[${level}][${urgensi}][${skor}/100] ${d.judul_sinyal}: ${d.deskripsi_sinyal || '—'}${hukum}`;
  })
  .join('\n');

// ── Sumber breakdown ─────────────────────────────────────────────────────────
const dari_wa     = today.filter(i => i.json.jenis_sumber === 'whatsapp').length;
const dari_manual = today.filter(i => i.json.jenis_sumber === 'input-manual').length;

return [{
  json: {
    tanggal       : todayStr,
    total         : today.length,
    // Level
    mikro, meso, makro,
    // Urgensi
    rendah, sedang, tinggi,
    // Status
    open, eskalasi,
    // Sumber
    dari_wa, dari_manual,
    // Untuk AI
    teks_konteks
  }
}];

