// Node ini SELALU jalan karena trigger punya 1 item
// Baca followup_log via Sheets API langsung — tidak bergantung pada jumlah baris
// Return 1 item berisi logMap (kosong jika sheet belum ada data)

const logMap = {};

try {
  // Ambil data dari sheet followup_log
  const sheetItems = await this.helpers.requestWithAuthentication.call(
    this,
    'googleSheetsOAuth2Api',
    {
      method: 'GET',
      url: 'https://sheets.googleapis.com/v4/spreadsheets/1SmLv-fLtv2-nqUhzFOfjJsmRttOcY6eXtl0Nu5n11q4/values/followup_log',
      json: true
    }
  );

  const rows = sheetItems.values || [];
  // rows[0] = header: [ticket_id, followup_ke, sent_at, channel, judul_sinyal]
  // rows[1+] = data
  if (rows.length > 1) {
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      const ticket_id = row[0];
      const followup_ke = parseInt(row[1]);
      if (!ticket_id || isNaN(followup_ke)) continue;
      if (logMap[ticket_id] === undefined || followup_ke > logMap[ticket_id]) {
        logMap[ticket_id] = followup_ke;
      }
    }
  }
} catch(e) {
  // Sheet belum ada atau error — logMap tetap kosong, flow tetap jalan
  console.log('followup_log kosong atau error:', e.message);
}

return [{ json: { logMap } }];

