const now = new Date();

const SLA_MAP = {
  'Tinggi': 24, 'High': 24, 'Hoog': 24,
  'Sedang': 48, 'Medium': 48, 'Gemiddeld': 48,
  'Rendah': 168, 'Low': 168, 'Laag': 168
};
const SLA_DEFAULT = 168;
const FOLLOWUP_WA_INTERVAL = 4;
const FOLLOWUP_CALL_JAM    = 24;
const MIN_URGENCY_SCORE    = 50;

function parseDate(str) {
  if (!str) return new Date(NaN);
  const d = new Date(String(str).trim().replace(' ', 'T'));
  return isNaN(d.getTime()) ? new Date(str) : d;
}
function toInt(v, def = 0) {
  const n = parseInt(v); return isNaN(n) ? def : n;
}
function getBaseId(tid) {
  const p = String(tid).split('-');
  return p.length > 3 ? p.slice(0, 3).join('-') : tid;
}

// logMap dari node sebelumnya — selalu ada karena Code node selalu return 1 item
const logMap = $items('Code: Baca + Agregasi Log')[0].json.logMap || {};

// De-duplikasi: pilih satu representatif per base_id (skor tertinggi)
const seen = new Map();
for (const item of items) {
  const d = item.json;
  if (!d.ticket_id) continue;
  const base_id = getBaseId(d.ticket_id);
  if (!seen.has(base_id)) {
    seen.set(base_id, item);
  } else if (toInt(d.skor_urgensi_hukum) > toInt(seen.get(base_id).json.skor_urgensi_hukum)) {
    seen.set(base_id, item);
  }
}

const output = [];
const skipped = [];

for (const item of seen.values()) {
  const d = item.json;
  if (d.status_ticket === 'Closed')                     { skipped.push(d.ticket_id + ' [closed]'); continue; }
  if (d.rekomendasi_keputusan?.trim())                  { skipped.push(d.ticket_id + ' [handled]'); continue; }
  if (toInt(d.skor_urgensi_hukum) < MIN_URGENCY_SCORE) { skipped.push(d.ticket_id + ' [skor rendah]'); continue; }

  const waktu_catat = parseDate(d.waktu_catat);
  if (isNaN(waktu_catat.getTime()))                     { skipped.push(d.ticket_id + ' [invalid date]'); continue; }

  const jam_berlalu   = (now - waktu_catat) / 3600000;
  const sla_jam       = SLA_MAP[d.urgensi_sinyal] || SLA_DEFAULT;
  const jam_terlambat = jam_berlalu - sla_jam;
  const followup_ke   = Math.floor(jam_berlalu / FOLLOWUP_WA_INTERVAL);
  const base_id       = getBaseId(d.ticket_id);

  // Anti-spam: cek log
  const followup_terakhir = logMap[base_id] !== undefined ? logMap[base_id] : -1;
  if (followup_ke <= followup_terakhir) {
    skipped.push(base_id + ' [fup-' + followup_ke + ' sudah dikirim, log=' + followup_terakhir + ']');
    continue;
  }

  const perlu_telepon = jam_berlalu >= FOLLOWUP_CALL_JAM;
  const channel       = perlu_telepon ? 'voice_call' : 'whatsapp';
  const perlu_email   = true;

  output.push({
    json: {
      ...d,
      sla_jam,
      jam_berlalu:      Math.round(jam_berlalu * 10) / 10,
      terlambat_jam:    jam_terlambat > 0 ? Math.round(jam_terlambat * 10) / 10 : 0,
      sisa_sla_jam:     jam_terlambat <= 0 ? Math.round((sla_jam - jam_berlalu) * 10) / 10 : 0,
      followup_ke,
      status_eskalasi:  jam_terlambat > 0 ? 'Escalated' : 'Follow-up',
      eskalasi_channel: channel,
      perlu_telepon,
      perlu_email,
      aksi_followup:    perlu_telepon
        ? 'TELEPON - tidak ada respon ' + Math.round(jam_berlalu) + ' jam'
        : 'Follow-up WA ke-' + followup_ke,
      waktu_eskalasi:   now.toISOString(),
      _log_base_id:     base_id,
      _log_followup_ke: followup_ke,
      _log_sent_at:     now.toISOString()
    }
  });
}

if (output.length === 0) {
  return [{ json: { _skip: true, checked_at: now.toISOString(), skipped } }];
}

// Sort by skor_urgensi_hukum tertinggi, lalu ambil 1 saja
output.sort((a, b) => {
  const skorB = toInt(b.json.skor_urgensi_hukum);
  const skorA = toInt(a.json.skor_urgensi_hukum);
  if (skorB !== skorA) return skorB - skorA;
  // Jika skor sama, prioritaskan yang jam_berlalu lebih lama
  return b.json.jam_berlalu - a.json.jam_berlalu;
});

const MAX_PER_RUN = 1;
return output.slice(0, MAX_PER_RUN);
return output;
